135: function hasAlgorithm (token: string, algorithm: string) {
136:   const header = JSON.parse(Buffer.from(token.split('.')[0], 'base64').toString())
137:   return token && header && header.alg === algorithm
138: }
139: 
140: function hasEmail (token: { data: { email: string } }, email: string | RegExp) {
141:   return token?.data?.email?.match(email)
142: }
