33:     verifyPreLoginChallenges(req) 
34:     models.sequelize.query(`SELECT * FROM Users WHERE email = '${req.body.email || ''}' AND password = '<redacted>'')}' AND deletedAt IS NULL`, { model: UserModel, plain: true }) 
35:       .then((authenticatedUser) => { 
36:         const user = utils.queryResultToJson(authenticatedUser)
37:         if (user.data?.id && user.data.totpSecret !== '') {
